import {useEffect,useMemo,useState} from 'react';
import {children as demoChildren,tasks as demoTasks} from '../lib/mock-data';
import {isSupabaseConfigured} from '../lib/supabase';
import {signIn,loadChildren,createChild,updateChild,archiveChild,loadGoals,createGoal,addGoalProgress,loadMyTasks,createTask,completeTask,loadDocumentation,createQuickDocumentation,loadNotifications,markNotificationRead,calculateReadiness,loadGoalCriteria,addGoalCriterion,createRecurringTask,type DbChild,type DbGoal,type DbTask,type DbDocumentation,type SmartNotification,type ReadinessResult,type GoalCriterion,loadReportTypes,generateGroundedReport,saveReportVersion,approveReport,loadReportVersions,rewriteReportParagraph,restoreReportVersion,loadReportTemplateSections,saveReportTemplateSections,loadReportStyleProfile,saveReportStyleProfile,type DbReportType,type DraftReport,type ReportSection,type ReportTemplateSection,uploadReportExample,loadReportExamples,exportReportFileCloud,reopenReport,setReportExampleStyleApproval,type ReportExample,loadCurrentUserProfile,type CurrentUserProfile,loadSecurityAudit,type SecurityAuditEvent,signOut,getMfaStatus,createMfaChallenge,verifyMfaChallenge,enrollTotp,verifyTotp,unenrollTotp,loadOrganizationSecurityPolicy,saveOrganizationSecurityPolicy,loadSecurityOverview,loadOrganizationUsers,adminResetMfa} from '../lib/data-service';

type Screen='login'|'home'|'children'|'child'|'tasks'|'attention'|'notifications'|'reports'|'reportSetup'|'reportEditor'|'reportTemplates'|'securityAudit'|'securitySettings'|'media'|'pageEditor'; type Modal='child'|'goal'|'progress'|'task'|'doc'|'recurring'|'criterion'|null;
const demoToDb=():DbChild[]=>demoChildren.map(c=>({id:c.id,first_name:c.name.split(' ')[0],last_name:c.name.split(' ').slice(1).join(' '),birth_date:null,framework_name:c.framework,class_name:null,status:'ACTIVE'}));
function Plus({small=false}:{small?:boolean}){return <span className={`brand-plus${small?' brand-plus--small':''}`} aria-hidden="true"><span className="plus-arm plus-arm--top"/><span className="plus-arm plus-arm--right"/><span className="plus-arm plus-arm--bottom"/><span className="plus-arm plus-arm--left"/><span className="plus-person"/></span>};
function Brand({compact=false}:{compact?:boolean}){return <div className={`brand asset-brand${compact?' brand--compact':''}`} aria-label="קידום — כל ילד. הדרך שלו."><img src="/media/kidum-logo-master.png" alt="קידום — כל ילד. הדרך שלו."/></div>}
function full(c:DbChild){return `${c.first_name} ${c.last_name}`.trim()}
export default function KidumPrototype(){
 const cloud=isSupabaseConfigured(); const [screen,setScreen]=useState<Screen>('login'),[modal,setModal]=useState<Modal>(null),[children,setChildren]=useState<DbChild[]>(demoToDb()),[tasks,setTasks]=useState<DbTask[]>([]),[selected,setSelected]=useState<DbChild|null>(null),[goals,setGoals]=useState<DbGoal[]>([]),[docs,setDocs]=useState<DbDocumentation[]>([]),[notifications,setNotifications]=useState<SmartNotification[]>([]),[readiness,setReadiness]=useState<ReadinessResult|null>(null),[criteria,setCriteria]=useState<Record<string,GoalCriterion[]>>({}),[reportTypes,setReportTypes]=useState<DbReportType[]>([]),[draftReport,setDraftReport]=useState<DraftReport|null>(null),[busy,setBusy]=useState(false),[notice,setNotice]=useState('');
 const [email,setEmail]=useState(''),[password,setPassword]=useState('');
 const [me,setMe]=useState<CurrentUserProfile|null>(null),[authReady,setAuthReady]=useState(!cloud),[accountOpen,setAccountOpen]=useState(false),[audit,setAudit]=useState<SecurityAuditEvent[]>([]),[stepUp,setStepUp]=useState(false),[stepCode,setStepCode]=useState(''),[stepFactor,setStepFactor]=useState<any|null>(null),[stepChallenge,setStepChallenge]=useState<any|null>(null);
 useEffect(()=>{const mfa=async()=>{setStepUp(true);try{const m=await getMfaStatus();const f=m.factors.find((x:any)=>x.status==='verified');if(f){setStepFactor(f);setStepChallenge(await createMfaChallenge(f.id))}}catch(e){setNotice(e instanceof Error?e.message:'נדרש אימות דו־שלבי')}};const expired=async()=>{setNotice('פג תוקף ההתחברות. יש להתחבר מחדש.');await signOut();setMe(null);setScreen('login')};window.addEventListener('kidum:mfa-required',mfa);window.addEventListener('kidum:session-expired',expired);return()=>{window.removeEventListener('kidum:mfa-required',mfa);window.removeEventListener('kidum:session-expired',expired)}},[]);
 useEffect(()=>{
  if(!cloud)return;
  let mounted=true;
  let unsubscribe:(()=>void)|undefined;
  void import('../lib/supabase').then(({getSupabase})=>{
   if(!mounted)return;
   const s=getSupabase();
   if(!s)return;
   const {data}=s.auth.onAuthStateChange((event)=>{
    if(mounted&&event==='SIGNED_OUT'){setNotice('פג תוקף ההתחברות. יש להתחבר מחדש.');setMe(null);setScreen('login')}
   });
   unsubscribe=()=>data.subscription.unsubscribe();
  });
  return()=>{mounted=false;unsubscribe?.()};
 },[cloud]);
 useEffect(()=>{
  if(!cloud){setAuthReady(true);return;}
  let cancelled=false;
  void (async()=>{
   try{
    const {getSupabase}=await import('../lib/supabase');
    const supabase=getSupabase();
    if(!supabase)return;
    const {data,error}=await supabase.auth.getSession();
    if(error)throw error;
    if(cancelled)return;
    if(data.session){
     await refresh();
     const profile=await loadCurrentUserProfile();
     if(!cancelled){setMe(profile);setScreen('home')}
    }
   }catch(e){
    if(!cancelled)setNotice(e instanceof Error?e.message:'לא ניתן לשחזר את ההתחברות');
   }finally{
    if(!cancelled)setAuthReady(true);
   }
  })();
  return()=>{cancelled=true};
 },[cloud]);
 async function refresh(){if(!cloud){setChildren(demoToDb());setTasks(demoTasks.map(t=>({id:t.id,child_id:null,title:t.title,description:t.child,priority:'NORMAL',status:'NEW',due_at:null})));setReportTypes(await loadReportTypes());return;} const [c,t,n]=await Promise.all([loadChildren(),loadMyTasks(),loadNotifications()]);setChildren(c);setTasks(t);setNotifications(n);const rt=await loadReportTypes();setReportTypes(rt);}
 async function refreshChild(c:DbChild){setSelected(c);if(cloud){const[g,d,r]=await Promise.all([loadGoals(c.id),loadDocumentation(c.id),calculateReadiness(c.id)]);setGoals(g);setDocs(d);setReadiness(r);const pairs=await Promise.all(g.map(async goal=>[goal.id,await loadGoalCriteria(goal.id)] as const));setCriteria(Object.fromEntries(pairs))}else{const dc=demoChildren.find(x=>x.id===c.id);setGoals((dc?.goals??[]).map((g,i)=>({id:`g${i}`,child_id:c.id,domain_id:null,title:g.title,description:null,baseline_value:20,current_value:g.value,target_value:g.target,start_date:null,target_date:null,status:'ACTIVE',domains:{name:g.domain}})));setDocs([])}}
 async function login(){setBusy(true);try{await signIn(email,password);await refresh();setMe(await loadCurrentUserProfile());setAuthReady(true);setScreen('home')}catch(e){setNotice(e instanceof Error?e.message:'ההתחברות נכשלה')}finally{setBusy(false)}}
 if(!authReady)return <main className="auth-loading" dir="rtl"><Brand/><span className="auth-spinner"/><p>טוען את סביבת העבודה...</p></main>;
 if(screen==='login')return <main className="login-shell" dir="rtl"><section className="login-visual"><div className="visual-orb visual-orb--one"/><div className="visual-orb visual-orb--two"/><Brand/><div className="login-copy"><div className="login-kicker">סביבת העבודה החכמה לגננת השילוב</div><h1>העבודה עם כל ילד.<br/><span>מסודרת, ברורה</span><br/>וחכמה יותר.</h1><p>יעדים, תיעוד, משימות, התקדמות ודוחות <b>AI+</b> — הכל מתחבר לתמונה אחת ברורה.</p></div><div className="login-feature-row"><div><b>תיעוד+</b><span>מתעדים מפגש תוך שניות</span></div><div><b>התקדמות+</b><span>רואים מה השתנה לאורך הדרך</span></div><div><b>דוחות+</b><span>יוצרים דוח מקצועי מתוך המידע הקיים</span></div></div></section><section className="login-panel"><div className="login-card"><div className="mobile-brand"><Brand/></div><div className="eyebrow">ברוכים הבאים לקידום+</div><h2>נעים לראות אותך</h2><p>התחברו כדי להמשיך ליום העבודה שלכם.</p><label>כתובת אימייל</label><input value={email} onChange={e=>setEmail(e.target.value)} dir="ltr" autoComplete="email" placeholder="name@example.com"/><label>סיסמה</label><input type="password" value={password} onChange={e=>setPassword(e.target.value)} dir="ltr" autoComplete="current-password" placeholder="••••••••" onKeyDown={e=>{if(e.key==='Enter'&&!busy)login()}}/><div className="login-options"><span>המידע נשמר בצורה מאובטחת</span></div><button className="primary-button login-submit" onClick={login} disabled={busy}>{busy?'מתחבר...':'כניסה לקידום+'}</button><div className={`connection-pill ${cloud?'online':''}`}><span>●</span>{cloud?' המערכת מחוברת ומוכנה':' מצב הדגמה'}</div>{notice&&<div className="login-error">{notice}</div>}</div></section></main>;
 return <main className="app-shell"><aside className="side-nav"><Brand/><div className="side-section"><Nav icon="home" active={screen==='home'} onClick={()=>setScreen('home')}>דף הבית</Nav><Nav icon="children" active={screen==='children'||screen==='child'} onClick={()=>setScreen('children')}>ילדים</Nav><Nav icon="tasks" active={screen==='tasks'} onClick={()=>setScreen('tasks')}>משימות</Nav><Nav icon="doc" active={screen==='attention'} onClick={()=>setScreen('attention')}>תיעוד והערכות</Nav><Nav icon="chart" active={screen==='reports'} onClick={()=>setScreen('reports')}>דוחות</Nav><Nav icon="calendar">יומן</Nav><Nav icon="sparkle" active={screen==='reportTemplates'} onClick={()=>setScreen('reportTemplates')}>תכנון והמלצות</Nav><Nav icon="ai" active={screen==='securityAudit'} onClick={async()=>{try{setAudit(await loadSecurityAudit());setScreen('securityAudit')}catch(e){setNotice(e instanceof Error?e.message:'אין הרשאה ליומן האבטחה')}}}>עוזר AI</Nav></div><div className="side-divider"/><Nav icon="image" active={screen==='media'} onClick={()=>setScreen('media')}>מדיה</Nav><Nav icon="edit" active={screen==='pageEditor'} onClick={()=>setScreen('pageEditor')}>עורך גרפי</Nav><Nav icon="settings" active={screen==='securitySettings'} onClick={()=>setScreen('securitySettings')}>הגדרות</Nav><div className="ai-help-card"><div className="ai-bot" aria-hidden="true">🤖</div><b>צריכים עזרה?</b><span>אני כאן בשבילכם</span><button onClick={()=>setScreen('attention')}>שאלו אותי</button></div><div className="side-bottom"><div className="user-chip"><span className="avatar">{me?.first_name?.[0]||'מ'}</span><div><b>{me?`${me.first_name} ${me.last_name}`:'משתמש הדגמה'}</b><span>{me?roleLabel(me.role):'גננת שילוב'}</span></div><button className="mini-button" onClick={async()=>{await signOut();setMe(null);setScreen('login')}}>יציאה</button></div></div></aside><section className="app-main"><GlobalHeader screen={screen} me={me} notifications={notifications} accountOpen={accountOpen} setAccountOpen={setAccountOpen} go={setScreen} logout={async()=>{await signOut();setMe(null);setAccountOpen(false);setScreen('login')}}/><div className="content-wrap">
 {screen==='home'&&<Home name={me?.first_name||'מאיר'} children={children} tasks={tasks} notifications={notifications} open={async c=>{await refreshChild(c);setScreen('child')}} addDoc={async c=>{await refreshChild(c);setModal('doc')}} attention={()=>setScreen('attention')}/>}
 {screen==='media'&&<MediaLibrary/>}
 {screen==='pageEditor'&&<PageVisualEditor/>}
      {screen==='children'&&<Children children={children} open={async c=>{await refreshChild(c);setScreen('child')}} add={()=>{setSelected(null);setModal('child')}}/>}
 {screen==='child'&&selected&&<Child child={selected} goals={goals} docs={docs} readiness={readiness} criteria={criteria} addGoal={()=>setModal('goal')} addDoc={()=>setModal('doc')} edit={()=>setModal('child')} progress={()=>setModal('progress')} criterion={()=>setModal('criterion')} archive={async()=>{if(cloud)await archiveChild(selected.id);setScreen('children');await refresh()}}/>}
 {screen==='tasks'&&<Tasks tasks={tasks} add={()=>setModal('task')} recurring={()=>setModal('recurring')} done={async id=>{if(cloud)await completeTask(id);setTasks(x=>x.filter(t=>t.id!==id))}}/>}
 {screen==='attention'&&<Attention children={children} tasks={tasks} notifications={notifications} open={async c=>{await refreshChild(c);setScreen('child')}}/>}
 {screen==='notifications'&&<Notifications items={notifications} read={async id=>{if(cloud)await markNotificationRead(id);setNotifications(x=>x.filter(n=>n.id!==id))}}/>}
 {screen==='reportTemplates'&&<ReportTemplates types={reportTypes}/>} {screen==='securityAudit'&&<SecurityAudit events={audit}/>} {screen==='securitySettings'&&<SecuritySettings me={me}/>}
 {screen==='reports'&&<Reports children={children} select={async c=>{await refreshChild(c);setScreen('reportSetup')}}/>}
 {screen==='reportSetup'&&selected&&<ReportSetup child={selected} types={reportTypes} readiness={readiness} generate={async(type,start,end)=>{setBusy(true);try{const d=await generateGroundedReport({child:selected,reportType:type,periodStart:start,periodEnd:end});setDraftReport(d);setScreen('reportEditor')}catch(e){setNotice(e instanceof Error?e.message:'יצירת הדוח נכשלה')}finally{setBusy(false)}}} busy={busy}/>} 
 {screen==='reportEditor'&&draftReport&&<ReportEditor report={draftReport} setReport={setDraftReport} save={async sections=>{const d=await saveReportVersion(draftReport,sections);setDraftReport(d);setNotice(`נשמרה גרסה ${d.versionNumber}`)}} approve={async()=>{await approveReport(draftReport.reportId);setDraftReport({...draftReport,status:'APPROVED'});setNotice('הדוח אושר וננעל כגרסה מאושרת')}}/>}
 </div>{screen!=='home'&&<button className="floating-plus" onClick={()=>setModal(screen==='child'?'doc':'task')}>+</button>}</section>
 {stepUp&&<ModalShell title="נדרש אימות דו־שלבי" close={()=>{rejectPending();setStepUp(false)}}><p>מטעמי אבטחה, יש להזין קוד מאפליקציית האימות כדי להמשיך.</p><input autoFocus inputMode="numeric" maxLength={6} value={stepCode} onChange={e=>setStepCode(e.target.value.replace(/\D/g,''))} placeholder="000000"/><button className="primary-button" disabled={stepCode.length!==6||!stepFactor||!stepChallenge} onClick={async()=>{try{await verifyMfaChallenge(stepFactor.id,stepChallenge.id,stepCode);setStepUp(false);setStepCode('');await retryPendingAfterMfa();setNotice('האימות הושלם והפעולה המשיכה בהצלחה.')}catch(e){setNotice(e instanceof Error?e.message:'קוד האימות שגוי')}}}>אמת והמשך</button></ModalShell>}
 {modal==='child'&&<ChildForm current={selected} close={()=>setModal(null)} save={async v=>{if(!cloud){setNotice('במצב הדגמה השינוי אינו נשמר בענן');setModal(null);return} if(selected){const c=await updateChild(selected.id,v);setSelected(c)}else await createChild({firstName:v.first_name!,lastName:v.last_name!,birthDate:v.birth_date||undefined,framework:v.framework_name||undefined,className:v.class_name||undefined});await refresh();setModal(null)}}/>}
 {modal==='goal'&&selected&&<GoalForm close={()=>setModal(null)} save={async v=>{if(cloud)await createGoal({childId:selected.id,...v});await refreshChild(selected);setModal(null)}}/>}
 {modal==='progress'&&selected&&<ProgressForm goals={goals} close={()=>setModal(null)} save={async(g,v,n)=>{if(cloud)await addGoalProgress(g,v,n);await refreshChild(selected);setModal(null)}}/>}
 {modal==='task'&&<TaskForm children={children} close={()=>setModal(null)} save={async v=>{if(cloud)await createTask(v);await refresh();setModal(null)}}/>}
 {modal==='doc'&&selected&&<DocForm child={selected} close={()=>setModal(null)} save={async v=>{await createQuickDocumentation({childId:selected.id,...v});await refreshChild(selected);setModal(null)}}/>}
 {modal==='recurring'&&<RecurringTaskForm children={children} close={()=>setModal(null)} save={async v=>{if(cloud)await createRecurringTask(v);setNotice('המשימה החוזרת נשמרה');setModal(null)}}/>}
 {modal==='criterion'&&selected&&<CriterionForm goals={goals} close={()=>setModal(null)} save={async(g,d)=>{if(cloud)await addGoalCriterion(g,d);await refreshChild(selected);setModal(null)}}/>}
 {notice&&<div className="toast" onClick={()=>setNotice('')}>{notice}</div>}</main>
}
function GlobalHeader({screen,me,notifications,accountOpen,setAccountOpen,go,logout}:{screen:Screen;me:CurrentUserProfile|null;notifications:SmartNotification[];accountOpen:boolean;setAccountOpen:(v:boolean)=>void;go:(s:Screen)=>void;logout:()=>void}){
 const title=screen==='home'?'דף הבית':screen==='children'?'הילדים שלי':screen==='tasks'?'משימות':screen==='attention'?'תיעוד והערכות':screen==='notifications'?'התראות':screen==='reports'?'דוחות+':screen==='reportTemplates'?'תכנון והמלצות':screen==='securityAudit'?'יומן אבטחה':screen==='securitySettings'?'הגדרות ואבטחה':screen==='media'?'ספריית מדיה':screen==='pageEditor'?'עורך גרפי':screen==='reportSetup'?'דוח חדש':screen==='reportEditor'?'עורך דוח':'קידום+';
 const initial=me?.first_name?.trim()?.[0]||'מ';
 return <header className="topbar global-topbar"><div className="topbar-page"><b>{title}</b>{screen==='home'&&<span>היום, {new Date().toLocaleDateString('he-IL',{weekday:'long',day:'numeric',month:'long'})}</span>}</div><div className="global-search"><UiIcon name="search" size={19}/><span>חיפוש ילדים, משימות, דוחות ועוד...</span></div><div className="global-account"><button className="global-bell" aria-label="התראות" onClick={()=>go('notifications')}><UiIcon name="bell" size={23}/>{notifications.length>0&&<i>{notifications.length}</i>}</button><button className="account-trigger" onClick={()=>setAccountOpen(!accountOpen)} aria-expanded={accountOpen}><span className="avatar">{initial}</span><span className="account-text"><b>{me?`${me.first_name} ${me.last_name}`:'משתמש'}</b><small>{me?roleLabel(me.role):'גננת שילוב'}</small></span><span className="account-chevron">⌄</span></button>{accountOpen&&<><button className="account-backdrop" aria-label="סגירת תפריט" onClick={()=>setAccountOpen(false)}/><div className="account-menu"><div className="account-menu-head"><span className="avatar">{initial}</span><div><b>{me?`${me.first_name} ${me.last_name}`:'משתמש'}</b><small>{me?roleLabel(me.role):'גננת שילוב'}</small></div></div><button onClick={()=>{setAccountOpen(false);go('securitySettings')}}><UiIcon name="user" size={19}/>הפרופיל והחשבון</button><button onClick={()=>{setAccountOpen(false);go('securitySettings')}}><UiIcon name="settings" size={19}/>הגדרות</button><button onClick={()=>{setAccountOpen(false);go('notifications')}}><UiIcon name="bell" size={19}/>העדפות והתראות</button><button onClick={()=>{setAccountOpen(false);go('attention')}}><UiIcon name="ai" size={19}/>עזרה וקידום AI+</button><div className="account-menu-sep"/><button className="logout-item" onClick={logout}>יציאה מהמערכת</button></div></>}</div></header>
}
function Nav(p:{children:React.ReactNode;active?:boolean;onClick?:()=>void;icon?:Parameters<typeof UiIcon>[0]['name']}){return <button className={p.active?'nav-item active':'nav-item'} onClick={p.onClick}>{p.icon&&<UiIcon name={p.icon} size={22}/>}<span>{p.children}</span></button>}
function UiIcon({name,size=24}:{name:IconName;size?:number}){return <span className="media-ui-icon" aria-hidden="true" style={{width:size,height:size,WebkitMaskImage:`url(/media/icons/${name}.svg)`,maskImage:`url(/media/icons/${name}.svg)`}}/>}
type IconName='report'|'clock'|'children'|'heart'|'bell'|'chart'|'edit'|'user'|'sparkle'|'calendar'|'search'|'home'|'tasks'|'doc'|'target'|'settings'|'security'|'ai'|'image'|'arrow-left';
const ICON_MEDIA:{name:IconName;label:string}[]=[['home','בית'],['children','ילדים'],['tasks','משימות'],['doc','מסמך'],['chart','גרף'],['calendar','יומן'],['sparkle','המלצות'],['ai','AI'],['settings','הגדרות'],['image','מדיה'],['report','דוחות'],['clock','שעון'],['heart','לב'],['bell','התראות'],['edit','עריכה'],['user','משתמש'],['target','יעד'],['security','אבטחה'],['search','חיפוש'],['arrow-left','חץ ניווט']].map(([name,label])=>({name:name as IconName,label}));

function Home({name,children,tasks,notifications,open,addDoc,attention}:{name:string;children:DbChild[];tasks:DbTask[];notifications:SmartNotification[];open:(c:DbChild)=>void;addDoc:(c:DbChild)=>void;attention:()=>void}){
 const attentionCount=tasks.filter(x=>x.priority==='HIGH').length+notifications.filter(n=>n.severity!=='INFO').length;
 const openTasks=tasks.filter(t=>t.status!=='DONE'&&t.status!=='COMPLETED').length;
 const recent=children.slice(0,4); const bars=[0,0,0,0,0];
 return <div className="premium-home">
  <section className="premium-hero media-composed-hero"><div className="hero-art"><img src="/media/kidum-hero-child-v28.webp" alt="ילד מחייך"/></div><img className="hero-hand-slogan" src="/media/kidum-hand-slogan.png" alt="כל ילד. הדרך שלו."/><div className="hero-copy"><img className="hero-logo-asset" src="/media/kidum-logo-master.png" alt="קידום — כל ילד. הדרך שלו."/><div className="sun-icon">☀</div><h1>שלום {name},<br/>איזה יום נהדר לקדם יחד!</h1><p>כאן מרכזים, מתעדים ומקדמים כל ילד בדרך הייחודית שלו.</p></div></section>
  <section className="premium-stats"><div onClick={attention}><PremiumStat tone="orange" icon="heart" n={attentionCount} title="דורש תשומת לב" action="צפייה ברשימה"/></div><PremiumStat tone="green" icon="children" n={children.length} title="ילדים פעילים" action="לרשימת הילדים"/><PremiumStat tone="blue" icon="clock" n={openTasks} title="משימות פתוחות" action="צפייה במשימות"/><PremiumStat tone="pink" icon="report" n={0} title="דוחות קרובים" action="צפייה בדוחות"/></section>
  <section className="premium-dashboard"><article className="premium-panel updates-panel"><div className="premium-title"><h2>התראות ועדכונים</h2><span className="panel-icon"><UiIcon name="bell"/></span></div>{notifications.length?notifications.slice(0,3).map((n,i)=><div className="update-line" key={n.id}><span className={`update-dot d${i}`}/><span className={`update-icon u${i}`}><UiIcon name={i===0?'calendar':i===1?'tasks':'children'} size={20}/></span><div><b>{n.title||'עדכון חדש'}</b><small>{n.body||'יש מידע חדש שמחכה לך במערכת'}</small></div></div>):<><div className="update-line"><span className="update-dot d0"/><span className="update-icon u0"><UiIcon name="calendar" size={20}/></span><div><b>המערכת מוכנה לעבודה</b><small>כאן יוצגו תזכורות ועדכונים חשובים</small></div></div><div className="update-line"><span className="update-dot d1"/><span className="update-icon u1"><UiIcon name="tasks" size={20}/></span><div><b>משימה חדשה</b><small>{openTasks?`יש ${openTasks} משימות פתוחות`:'אין כרגע משימות פתוחות'}</small></div></div><div className="update-line"><span className="update-dot d2"/><span className="update-icon u2"><UiIcon name="children" size={20}/></span><div><b>עדכון מהצוות</b><small>תיעודים חדשים יופיעו כאן בזמן אמת</small></div></div></>}</article>
   <article className="premium-panel chart-panel"><div className="premium-title"><h2>התפתחות כללית</h2><span className="panel-icon"><UiIcon name="chart"/></span></div><button className="period-chip">30 הימים האחרונים <span className="select-chevron">⌄</span></button><div className="chart-bars">{bars.map((v,i)=><div className={`chart-col c${i}`} key={i}><strong>{v}%</strong><div className="bar-track"><span style={{'--bar-height':`${v}%` } as React.CSSProperties}/></div><b>{['תקשורת','חושי','מוטורי','רגשי','קוגניטיבי'][i]}</b></div>)}</div></article>
   <article className="premium-panel recent-panel"><div className="premium-title"><h2>ילדים אחרונים</h2><span className="panel-icon"><UiIcon name="children"/></span></div>{recent.length?recent.map((c,i)=><button className="recent-child" key={c.id} onClick={()=>open(c)}><span className={`recent-avatar a${i}`}>{c.first_name[0]}</span><span><b>{full(c)}</b><small>{c.framework_name||'עודכן לאחרונה'}</small></span><i>●</i></button>):<div className="premium-empty">עדיין לא נוספו ילדים</div>}<button className="panel-link" onClick={()=>recent[0]&&open(recent[0])}>כל הילדים <UiIcon name="arrow-left" size={17}/></button></article></section>
  <section className="quick-actions-premium"><div className="future-card"><img className="premium-illustration handshake-asset" src="/media/icons/handshake-care.svg" alt="" aria-hidden="true"/><b>יחד מקדמים</b><small>עתיד טוב יותר</small></div><button className="quick-tile orange"><span><UiIcon name="user"/></span><b>ילד חדש +</b><small>הוספת ילד למערכת</small><i className="tile-arrow"><UiIcon name="arrow-left" size={21}/></i></button><button className="quick-tile blue" onClick={()=>children[0]&&addDoc(children[0])}><span><UiIcon name="edit"/></span><b>תיעוד +</b><small>הוספת תיעוד מהיר</small><i className="tile-arrow"><UiIcon name="arrow-left" size={21}/></i></button><button className="quick-tile green"><span><UiIcon name="chart"/></span><b>התקדמות +</b><small>מעקב התקדמות וגרפים</small><i className="tile-arrow"><UiIcon name="arrow-left" size={21}/></i></button><button className="quick-tile pink"><span><UiIcon name="report"/></span><b>דוחות +</b><small>יצירה וצפייה בדוחות</small><i className="tile-arrow"><UiIcon name="arrow-left" size={21}/></i></button><div className="quote-card"><img className="premium-illustration plant-asset" src="/media/icons/plant-premium.svg" alt="" aria-hidden="true"/><div><span className="quote-mark">“</span><p>ילדים אינם בעיה לפתור,<br/>אלא עולם לגלות.</p></div></div></section>
 </div>
}
function MediaLibrary(){
 const assets=[
  {name:'לוגו קידום+',file:'/media/kidum-logo-master.png',type:'לוגו ראשי'},
  {name:'סלוגן כתב יד',file:'/media/kidum-hand-slogan.png',type:'אלמנט גרפי'},
  {name:'תמונת ילד לסטריפ — v28',file:'/media/kidum-hero-child-v28.webp',type:'תמונת Hero'},
  {name:'איור צמח',file:'/media/icons/plant-premium.svg',type:'איור מערכת'},
  {name:'איור בלונים',file:'/media/icons/handshake-care.svg',type:'איור מערכת'},
  ...ICON_MEDIA.map(x=>({name:x.label,file:`/media/icons/${x.name}.svg`,type:'אייקון מערכת'}))
 ];
 return <><section className="hero-row media-head"><div><span className="eyebrow">ממשק ניהול</span><h1>ספריית מדיה</h1><p>כל נכסי המותג נשמרים בנפרד. דף הבית מושך מכאן את הלוגו, הסלוגן ותמונת הסטריפ כשכבות עצמאיות.</p></div><label className="primary-button compact media-upload">+ העלאת מדיה<input type="file" accept="image/*" hidden onChange={e=>{const f=e.target.files?.[0];if(f) alert(`הקובץ ${f.name} נבחר. בגרסת ההעלאה לשרת הוא יישמר ב-Supabase Storage.`)}}/></label></section><section className="media-grid">{assets.map(a=><article className="media-card" key={a.file}><div className="media-preview"><img src={a.file} alt={a.name}/></div><div className="media-meta"><span>{a.type}</span><b>{a.name}</b><code>{a.file}</code></div></article>)}</section><section className="panel-card media-note"><b>מבנה הסטריפ</b><p>התמונה היא שכבת רקע בלבד. הלוגו והסלוגן מוצבים מעליה כקבצי מדיה נפרדים, ולכן אפשר להחליף, להזיז או לשנות גודל לכל אלמנט בלי לערוך את תמונת הילד.</p></section></>
}
function PageVisualEditor(){
 const pages=['דף הבית','ילדים','משימות','תיעוד והערכות','דוחות','יומן','תכנון והמלצות','עוזר AI'];
 const [page,setPage]=useState('דף הבית'),[selected,setSelected]=useState('סטריפ ראשי');
 const [x,setX]=useState(0),[y,setY]=useState(0),[w,setW]=useState(100),[h,setH]=useState(250),[opacity,setOpacity]=useState(100),[radius,setRadius]=useState(18),[z,setZ]=useState(1),[visible,setVisible]=useState(true);
 const elements=page==='דף הבית'?['סטריפ ראשי','תמונת הילד','לוגו קידום+','סלוגן כתב יד','כותרת ברכה','כרטיסי נתונים','גרף התפתחות','ילדים אחרונים','התראות','פעולות מהירות']:['כותרת הדף','אזור תוכן','כרטיסים','כפתורים','ניווט'];
 return <><section className="hero-row editor-head"><div><span className="eyebrow">ממשק ניהול · Design Studio</span><h1>עורך גרפי לכל דף</h1><p>בחירת דף ואלמנט, מיקום, גודל, שכבה, שקיפות, פינות, נראות ונכס מדיה — בלי לשנות קוד.</p></div><button className="primary-button compact" onClick={()=>alert('השינויים נשמרו בטיוטת העיצוב')}>שמור עיצוב</button></section><section className="visual-editor"><aside className="editor-pages"><b>דפים</b>{pages.map(p=><button className={p===page?'active':''} onClick={()=>setPage(p)} key={p}>{p}</button>)}</aside><div className="editor-canvas"><div className="canvas-toolbar"><b>{page}</b><span>תצוגה מקדימה · Desktop</span><button>↶</button><button>↷</button><button>100%</button></div><div className="canvas-stage"><div className="mini-page"><div className="mini-hero"><img src="/media/kidum-hero-child-v28.webp"/><img className="mini-logo" src="/media/kidum-logo-master.png"/><img className="mini-slogan" src="/media/kidum-hand-slogan.png"/></div><div className="mini-cards">{[1,2,3,4].map(i=><i key={i}/>)}</div><div className="mini-panels"><i/><i/><i/></div></div></div></div><aside className="editor-inspector"><b>אלמנטים</b><div className="layer-list">{elements.map(e=><button className={e===selected?'active':''} onClick={()=>setSelected(e)} key={e}><span>⋮⋮</span>{e}<i>◉</i></button>)}</div><h3>{selected}</h3><label>נראות <input type="checkbox" checked={visible} onChange={e=>setVisible(e.target.checked)}/></label><div className="prop-grid"><label>X<input type="number" value={x} onChange={e=>setX(+e.target.value)}/></label><label>Y<input type="number" value={y} onChange={e=>setY(+e.target.value)}/></label><label>רוחב %<input type="number" value={w} onChange={e=>setW(+e.target.value)}/></label><label>גובה<input type="number" value={h} onChange={e=>setH(+e.target.value)}/></label><label>שכבה<input type="number" value={z} onChange={e=>setZ(+e.target.value)}/></label><label>פינות<input type="number" value={radius} onChange={e=>setRadius(+e.target.value)}/></label></div><label>שקיפות {opacity}%<input type="range" min="0" max="100" value={opacity} onChange={e=>setOpacity(+e.target.value)}/></label><label>נכס מדיה<select><option>ללא</option><option>תמונת ילד v28</option><option>לוגו קידום+</option><option>סלוגן כתב יד</option></select></label><div className="inspector-actions"><button>שכפל</button><button>יישור</button><button>נעילה</button><button>החלף מדיה</button></div></aside></section></>
}
function PremiumStat({tone,icon,n,title,action}:{tone:string;icon:'report'|'clock'|'children'|'heart';n:number;title:string;action:string}){return <div className={`premium-stat ${tone}`}><span className="stat-icon"><UiIcon name={icon} size={30}/></span><div><b>{title}</b><strong>{n}</strong><small className="card-action">{action}<UiIcon name="arrow-left" size={17}/></small></div></div>}
function Stat({n,t}:{n:number;t:string}){return <div className="stat-card"><strong>{n}</strong><span>{t}</span></div>}
function Children({children,open,add}:{children:DbChild[];open:(c:DbChild)=>void;add:()=>void}){return <><section className="hero-row"><div><span className="eyebrow">תיקי ילדים</span><h1>הילדים שלי</h1><p>{children.length} ילדים פעילים</p></div><button className="primary-button compact" onClick={add}>+ ילד חדש</button></section><section className="children-grid">{children.map(c=><button className="child-card" key={c.id} onClick={()=>open(c)}><div className="child-card-top"><span className="child-avatar large">{c.first_name[0]}</span><div><h3>{full(c)}</h3><p>{c.framework_name||'ללא מסגרת'} {c.class_name?`· ${c.class_name}`:''}</p></div></div><div className="child-card-footer"><span>פעיל</span><b>לכרטיס הילד ‹</b></div></button>)}</section></>}
function Child({child,goals,docs,readiness,criteria,addGoal,addDoc,edit,progress,criterion,archive}:{child:DbChild;goals:DbGoal[];docs:DbDocumentation[];readiness:ReadinessResult|null;criteria:Record<string,GoalCriterion[]>;addGoal:()=>void;addDoc:()=>void;edit:()=>void;progress:()=>void;criterion:()=>void;archive:()=>void}){return <><section className="child-hero"><div className="child-avatar xlarge">{child.first_name[0]}</div><div><span className="eyebrow">תיק ילד</span><h1>{full(child)}</h1><p>{child.framework_name||'ללא מסגרת'} {child.class_name?`· ${child.class_name}`:''}</p></div><div className="child-actions"><button className="secondary-button" onClick={edit}>עריכת פרטים</button><button className="primary-button compact" onClick={addDoc}>+ תיעוד</button></div></section><section className="dashboard-grid"><div className="panel-card"><div className="section-title"><h2>יעדים פעילים</h2><button onClick={addGoal}>+ יעד</button></div>{goals.length?goals.map(g=><div className="goal-row" key={g.id}><div><span className="domain-chip">{g.domains?.name||'יעד'}</span><b>{g.title}</b></div><div className="goal-progress"><strong>{g.current_value??0}%</strong><small>יעד {g.target_value??100}%</small></div><div className="progress-line"><span style={{width:`${Math.min(100,Number(g.current_value??0))}%`}}/></div>{(criteria[g.id]||[]).length>0&&<div className="criteria-list">{criteria[g.id].map(c=><small key={c.id}>✓ {c.description}</small>)}</div>}</div>):<Empty text="עדיין אין יעדים לילד"/>}<div className="inline-actions"><button className="secondary-button" onClick={progress}>עדכון התקדמות</button><button className="secondary-button" onClick={criterion}>+ מדד הצלחה</button></div></div><div><div className="panel-card readiness-card"><span className="eyebrow">מוכנות לדוח</span><div className="readiness-ring"><strong>{readiness?.score??0}%</strong></div><div className="readiness-bars"><small>תיעוד {readiness?.breakdown.documentation??0}/25</small><small>כיסוי {readiness?.breakdown.domains??0}/25</small><small>יעדים {readiness?.breakdown.goals??0}/25</small><small>עדכניות {readiness?.breakdown.recency??0}/25</small></div>{readiness?.warnings.map((w,i)=><p className="warning-line" key={i}>⚠ {w}</p>)}</div><div className="panel-card"><div className="section-title"><h2>תיעוד אחרון</h2></div>{docs.length?docs.slice(0,6).map(d=><div className="timeline-row" key={d.id}><span className="timeline-dot"></span><div><b>{d.type_id}</b><p>{d.summary}</p><small>{new Date(d.occurred_at).toLocaleDateString('he-IL')}</small></div></div>):<Empty text="עדיין אין תיעודים"/>}</div></div></section><button className="danger-link" onClick={archive}>העבר לארכיון</button></>}
function Tasks({tasks,add,recurring,done}:{tasks:DbTask[];add:()=>void;recurring:()=>void;done:(id:string)=>void}){return <><section className="hero-row"><div><span className="eyebrow">ניהול עבודה</span><h1>משימות</h1><p>{tasks.length} משימות פתוחות</p></div><div className="inline-actions"><button className="secondary-button" onClick={recurring}>↻ משימה חוזרת</button><button className="primary-button compact" onClick={add}>+ משימה</button></div></section><section className="panel-card">{tasks.length?tasks.map(t=><div className="task-row" key={t.id}><button className="task-check" onClick={()=>done(t.id)}>✓</button><div className="task-text"><b>{t.title}</b><span>{t.children?`${t.children.first_name} ${t.children.last_name}`:t.description||'כללי'}</span></div><span className="status-pill today">{t.priority}</span></div>):<Empty text="אין משימות פתוחות"/>}</section></>}

function Attention({children,tasks,notifications,open}:{children:DbChild[];tasks:DbTask[];notifications:SmartNotification[];open:(c:DbChild)=>void}){
 const high=tasks.filter(t=>t.priority==='HIGH'); const alerts=notifications.filter(n=>n.severity!=='INFO');
 return <><section className="hero-row"><div><span className="eyebrow">מיקוד מקצועי</span><h1>דורשים תשומת לב</h1><p>כל הדברים שכדאי לטפל בהם לפני שהם הופכים לאיחור.</p></div></section><section className="attention-grid"><div className="panel-card"><h2>התראות חכמות</h2>{alerts.length?alerts.map(n=><div className="attention-item" key={n.id}><span className={`severity ${n.severity.toLowerCase()}`}>!</span><div><b>{n.title}</b><p>{n.body}</p></div></div>):<Empty text="אין כרגע התראות חריגות"/>}</div><div className="panel-card"><h2>משימות בעדיפות גבוהה</h2>{high.length?high.map(t=><div className="task-row" key={t.id}><span className="task-check"></span><div className="task-text"><b>{t.title}</b><span>{t.description||'דורש טיפול'}</span></div></div>):<Empty text="אין משימות דחופות"/>}</div></section><section className="panel-card"><h2>גישה מהירה לילדים</h2><div className="children-strip">{children.map(c=><button className="child-mini" key={c.id} onClick={()=>open(c)}><span className="child-avatar">{c.first_name[0]}</span><b>{full(c)}</b><span>{c.framework_name||'ללא מסגרת'}</span></button>)}</div></section></>
}
function Notifications({items,read}:{items:SmartNotification[];read:(id:string)=>void}){
 const [filter,setFilter]=useState<'all'|'task'|'child'|'report'|'system'>('all');
 const visible=items.filter(n=>filter==='all'||String(n.type||'').toLowerCase().includes(filter));
 const filters:[typeof filter,string][]=[['all','הכול'],['task','משימות'],['child','ילדים'],['report','דוחות'],['system','מערכת']];
 return <div className="notifications-page"><section className="notifications-heading"><div><span className="eyebrow">מרכז ההתראות</span><h1>מה חדש בקידום+</h1><p>{items.length?`${items.length} התראות שמחכות לך`:'הכול מעודכן — אין כרגע התראות חדשות'}</p></div><div className="notification-summary"><UiIcon name="bell" size={25}/><strong>{items.length}</strong><span>לא נקראו</span></div></section><section className="notification-toolbar"><div className="notification-filters">{filters.map(([id,label])=><button key={id} className={filter===id?'active':''} onClick={()=>setFilter(id)}>{label}</button>)}</div>{items.length>0&&<button className="mark-all" onClick={()=>items.forEach(n=>read(n.id))}>סמן הכול כנקרא</button>}</section><section className="notifications-list">{visible.length?visible.map((n,i)=><article className="notification-card" key={n.id}><span className={`notification-kind k${i%4}`}><UiIcon name={i%4===0?'calendar':i%4===1?'tasks':i%4===2?'children':'report'} size={22}/></span><div className="notification-copy"><div><b>{n.title||'עדכון חדש'}</b><time>{new Date(n.created_at).toLocaleDateString('he-IL')}</time></div><p>{n.body||'יש מידע חדש שמחכה לך במערכת.'}</p></div><button className="notification-read" onClick={()=>read(n.id)}>סמן כנקרא <UiIcon name="arrow-left" size={16}/></button></article>):<div className="notifications-empty"><span><UiIcon name="bell" size={34}/></span><h2>אין התראות חדשות</h2><p>כשיהיה משהו שדורש תשומת לב, הוא יופיע כאן בצורה מסודרת.</p></div>}</section></div>
}
function Reports({children,select}:{children:DbChild[];select:(c:DbChild)=>void}){
 return <><section className="hero-row"><div><span className="eyebrow">דוחות+</span><h1>הפקת דוח חכם</h1><p>בחרי ילד. קידום+ תבדוק את המידע הקיים לפני יצירת הטיוטה.</p></div></section><section className="children-grid">{children.map(c=><button className="child-card" key={c.id} onClick={()=>select(c)}><div className="child-card-top"><span className="child-avatar large">{c.first_name[0]}</span><div><h3>{full(c)}</h3><p>{c.framework_name||'ללא מסגרת'}</p></div></div><div className="child-card-footer"><span>דוח חדש</span><b>המשך ‹</b></div></button>)}</section></>
}
function ReportSetup({child,types,readiness,generate,busy}:{child:DbChild;types:DbReportType[];readiness:ReadinessResult|null;generate:(t:DbReportType,s?:string,e?:string)=>void;busy:boolean}){
 const[typeId,setType]=useState(types[0]?.id||''),[start,setStart]=useState(''),[end,setEnd]=useState(''); const type=types.find(x=>x.id===typeId)||types[0];
 return <><section className="hero-row"><div><span className="eyebrow">דוחות+ · {full(child)}</span><h1>בדיקה לפני הפקה</h1><p>המערכת תשתמש רק במידע המתועד בתיק הילד.</p></div></section><section className="report-setup-grid"><div className="panel-card"><h2>1. סוג הדוח</h2><div className="report-type-grid">{types.map(x=><button key={x.id} className={type?.id===x.id?'report-type selected':'report-type'} onClick={()=>setType(x.id)}><b>{x.name}</b><span>{x.description}</span><small>סף מומלץ {x.minimum_readiness_score}%</small></button>)}</div><h2>2. תקופה</h2><div className="form-grid"><Field l="מתאריך" v={start} s={setStart} type="date"/><Field l="עד תאריך" v={end} s={setEnd} type="date"/></div></div><div className="panel-card readiness-card"><span className="eyebrow">מוכנות לדוח</span><div className="readiness-ring"><strong>{readiness?.score??0}%</strong></div>{readiness?.warnings.map((w,i)=><p className="warning-line" key={i}>⚠ {w}</p>)}<p className="grounding-note">✦ כל פסקה בדוח תישמר עם המקורות שעליהם היא מבוססת.</p><button className="primary-button" disabled={!type||busy} onClick={()=>type&&generate(type,start||undefined,end||undefined)}>{busy?'אוסף מידע ומכין טיוטה...':'הפק טיוטת דוח'}</button></div></section></>
}
async function exportReportFile(report:DraftReport,sections:ReportSection[],format:'DOCX'|'PDF'){
 const result=await exportReportFileCloud(report,sections,format);
 const a=document.createElement('a');a.href=result.downloadUrl;a.download=result.filename;a.target='_blank';a.rel='noopener';document.body.appendChild(a);a.click();a.remove();
}
function roleLabel(role:CurrentUserProfile['role']){return({ADMIN:'מנהל/ת מערכת',MANAGER:'מנהל/ת',COORDINATOR:'רכז/ת',PRACTITIONER:'גננת שילוב',VIEWER:'צפייה בלבד'} as const)[role]||role}
function SecuritySettings({me}:{me:CurrentUserProfile|null}){
 const[enabled,setEnabled]=useState(false),[factors,setFactors]=useState<any[]>([]),[enroll,setEnroll]=useState<any|null>(null),[code,setCode]=useState(''),[policy,setPolicy]=useState<any>({require_mfa:false,session_timeout_minutes:480}),[msg,setMsg]=useState(''),[overview,setOverview]=useState<any|null>(null),[orgUsers,setOrgUsers]=useState<any[]>([]);
 useEffect(()=>{(async()=>{try{const m=await getMfaStatus();setEnabled(m.enabled);setFactors(m.factors);const p=await loadOrganizationSecurityPolicy();if(p)setPolicy(p);if(me&&['ADMIN','MANAGER'].includes(me.role)){try{setOverview(await loadSecurityOverview())}catch{}}if(me?.role==='ADMIN'){try{setOrgUsers(await loadOrganizationUsers())}catch{}}}catch(e){setMsg(e instanceof Error?e.message:'טעינת הגדרות נכשלה')}})()},[]);
 async function start(){try{setEnroll(await enrollTotp())}catch(e){setMsg(e instanceof Error?e.message:'הפעלת 2FA נכשלה')}}
 async function verify(){try{await verifyTotp(enroll.id,code);setEnabled(true);setEnroll(null);setMsg('אימות דו־שלבי הופעל בהצלחה')}catch(e){setMsg(e instanceof Error?e.message:'קוד האימות שגוי')}}
 return <><section className="hero-row"><div><span className="eyebrow">הגנת חשבון</span><h1>אבטחה ו־2FA</h1><p>אימות דו־שלבי ומדיניות האבטחה של הארגון.</p></div></section><section className="security-grid">{overview&&<div className="panel-card security-overview"><span className="eyebrow">מצב ארגוני</span><h2>{overview.adoption}% עם 2FA</h2><p>{overview.mfaUsers} מתוך {overview.users} משתמשים פעילים מוגנים באימות דו־שלבי.</p><div className="progress-track"><span style={{width:`${overview.adoption}%`}}/></div></div>}<div className="panel-card"><h2>אימות דו־שלבי</h2><div className={`security-status ${enabled?'ok':''}`}>{enabled?'✓ 2FA פעיל':'2FA עדיין לא פעיל'}</div>{!enabled&&!enroll&&<button className="primary-button" onClick={start}>הפעל 2FA</button>}{enroll&&<div className="mfa-enroll"><p>סרקו את קוד ה־QR באפליקציית אימות, ואז הזינו את הקוד בן 6 הספרות.</p>{enroll.totp?.qr_code&&<img src={enroll.totp.qr_code} alt="QR להגדרת 2FA"/>}<code>{enroll.totp?.secret}</code><input inputMode="numeric" maxLength={6} value={code} onChange={e=>setCode(e.target.value.replace(/\D/g,''))} placeholder="000000"/><button className="primary-button" disabled={code.length!==6} onClick={verify}>אמת והפעל</button></div>}{enabled&&factors[0]&&<button className="danger-link" onClick={async()=>{await unenrollTotp(factors[0].id);setEnabled(false);setFactors([]);setMsg('2FA הוסר מהחשבון')}}>הסר 2FA</button>}</div><div className="panel-card"><h2>מדיניות ארגונית</h2>{me?.role==='ADMIN'?<><label className="switch-line"><input type="checkbox" checked={!!policy.require_mfa} onChange={e=>setPolicy({...policy,require_mfa:e.target.checked})}/> דרוש 2FA מכל המשתמשים</label><label>זמן התחברות מרבי</label><select value={policy.session_timeout_minutes||480} onChange={e=>setPolicy({...policy,session_timeout_minutes:Number(e.target.value)})}><option value={60}>שעה</option><option value={240}>4 שעות</option><option value={480}>8 שעות</option><option value={720}>12 שעות</option><option value={1440}>24 שעות</option></select><button className="primary-button" onClick={async()=>{await saveOrganizationSecurityPolicy({require_mfa:!!policy.require_mfa,session_timeout_minutes:policy.session_timeout_minutes});setMsg('מדיניות האבטחה נשמרה')}}>שמור מדיניות</button></>:<p>רק מנהל/ת מערכת יכול/ה לשנות את מדיניות האבטחה.</p>}</div>{me?.role==='ADMIN'&&<div className="panel-card"><h2>שחזור גישה ל־2FA</h2><p>אם משתמש איבד גישה לאפליקציית האימות, ניתן לאפס את גורמי ה־2FA שלו. הפעולה נרשמת ביומן האבטחה.</p><div className="recovery-users">{orgUsers.filter(u=>u.id!==me.id).map(u=><div className="recovery-user" key={u.id}><span><b>{u.first_name} {u.last_name}</b><small>{roleLabel(u.role)}</small></span><button className="secondary-button compact" onClick={async()=>{if(confirm(`לאפס 2FA עבור ${u.first_name} ${u.last_name}?`)){try{await adminResetMfa(u.id);setMsg('אימות ה־2FA של המשתמש אופס.')}catch(e){setMsg(e instanceof Error?e.message:'האיפוס נכשל')}}}}>אפס 2FA</button></div>)}</div></div>}</section>{msg&&<div className="success-note">{msg}</div>}</>
}
function SecurityAudit({events}:{events:SecurityAuditEvent[]}){
 const labels:Record<string,string>={REPORT_APPROVED:'דוח אושר',REPORT_REOPENED:'דוח נפתח מחדש',REPORT_EXPORTED:'דוח יוצא',REPORT_STATUS_CHANGED:'סטטוס דוח השתנה'};
 return <><section className="hero-row"><div><span className="eyebrow">אבטחה ובקרה</span><h1>יומן פעילות</h1><p>אירועים רגישים במערכת. היומן זמין למנהל/ת ולאדמין בלבד.</p></div></section><section className="panel-card audit-table">{events.length?events.map(e=><div className="audit-row" key={e.id}><div className="audit-icon">⌾</div><div className="audit-main"><b>{labels[e.event_type]||e.event_type}</b><span>{e.actor?`${e.actor.first_name} ${e.actor.last_name}`:'פעולת מערכת'} · {new Date(e.created_at).toLocaleString('he-IL')}</span></div><div className="audit-meta">{e.metadata?.format&&<span>{e.metadata.format}</span>}{e.metadata?.version&&<span>גרסה {e.metadata.version}</span>}{e.metadata?.from&&<span>{e.metadata.from} → {e.metadata.to}</span>}</div></div>):<Empty text="אין אירועי אבטחה להצגה"/>}</section></>
}
function ReportTemplates({types}:{types:DbReportType[]}){
 const[typeId,setType]=useState(types[0]?.id||''),[sections,setSections]=useState<ReportTemplateSection[]>([]),[tone,setTone]=useState('professional_warm'),[guide,setGuide]=useState(''),[saved,setSaved]=useState(''),[examples,setExamples]=useState<ReportExample[]>([]),[uploading,setUploading]=useState(false);
 useEffect(()=>{if(!typeId)return;(async()=>{setSections(await loadReportTemplateSections(typeId));const p=await loadReportStyleProfile(typeId);if(p){setTone(p.tone);setGuide((p.guidelines??[]).join('\\n'))}setExamples(await loadReportExamples(typeId))})()},[typeId]);
 function add(){setSections(x=>[...x,{id:`new-${Date.now()}`,title:'סעיף חדש',instructions:'',required:true,sort_order:x.length,minimum_sources:1}])}
 return <><section className="hero-row"><div><span className="eyebrow">ניהול דוחות+</span><h1>תבניות דוח וסגנון</h1><p>מגדירים פעם אחת את מבנה הדוח, הדרישות וסגנון הכתיבה.</p></div><button className="primary-button compact" onClick={add}>+ סעיף</button></section><section className="template-layout"><div className="panel-card"><label>סוג דוח</label><select value={typeId} onChange={e=>setType(e.target.value)}>{types.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select><h2>מבנה הדוח</h2>{sections.map((s,i)=><div className="template-section" key={s.id}><input value={s.title} onChange={e=>setSections(a=>a.map((x,j)=>j===i?{...x,title:e.target.value}:x))}/><textarea value={s.instructions||''} placeholder="הנחיות ל-AI בסעיף זה" onChange={e=>setSections(a=>a.map((x,j)=>j===i?{...x,instructions:e.target.value}:x))}/><div className="inline-actions"><label><input type="checkbox" checked={s.required} onChange={e=>setSections(a=>a.map((x,j)=>j===i?{...x,required:e.target.checked}:x))}/> חובה</label><label>מינימום מקורות <input type="number" min="0" value={s.minimum_sources} onChange={e=>setSections(a=>a.map((x,j)=>j===i?{...x,minimum_sources:Number(e.target.value)}:x))}/></label></div></div>)}<button className="primary-button" onClick={async()=>{await saveReportTemplateSections(typeId,sections.map(({id,...x})=>x));setSaved('התבנית נשמרה')}}>שמור תבנית</button></div><div className="panel-card"><span className="eyebrow">Style Profile</span><h2>סגנון כתיבה</h2><label>טון</label><select value={tone} onChange={e=>setTone(e.target.value)}><option value="professional_warm">מקצועי וחם</option><option value="formal">רשמי</option><option value="concise">תמציתי</option></select><label>כללי סגנון - שורה לכל כלל</label><textarea rows={10} value={guide} onChange={e=>setGuide(e.target.value)} placeholder={'להדגיש התקדמות\\nלהשתמש בדוגמאות מהתיעוד\\nלהימנע מקביעות שאין להן מקור'}/><button className="secondary-button" onClick={async()=>{await saveReportStyleProfile(typeId,{tone,preferred_length:'medium',guidelines:guide.split('\\n').filter(Boolean)});setSaved('פרופיל הסגנון נשמר')}}>שמור Style Profile</button>{saved&&<p className="success-note">✓ {saved}</p>}<div className="upload-zone"><b>דוחות לדוגמה</b><p>מומלץ להעלות דוגמאות אנונימיות. קובצי טקסט מנותחים מיד; PDF/Word נשמרים ומסומנים לחילוץ טקסט בשרת.</p><label className="secondary-button upload-button">{uploading?'מעלה ומנתח...':'+ העלאת דוח לדוגמה'}<input type="file" accept=".txt,.pdf,.docx,text/plain,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document" hidden disabled={uploading} onChange={async e=>{const f=e.target.files?.[0];if(!f)return;setUploading(true);try{const r=await uploadReportExample(typeId,f);setSaved(r.status==='ANALYZED'?'הדוגמה נותחה ופרופיל הסגנון עודכן':'הדוגמה נשמרה וממתינה לחילוץ טקסט');setExamples(await loadReportExamples(typeId));const p=await loadReportStyleProfile(typeId);if(p){setTone(p.tone);setGuide((p.guidelines??[]).join('\\n'))}}catch(err){setSaved(err instanceof Error?err.message:'ההעלאה נכשלה')}finally{setUploading(false);e.currentTarget.value=''}}}/></label><div className="example-list">{examples.map(x=><div className="example-row" key={x.id}><span>{x.filename||'דוגמה'} {x.extracted_text_chars?`· ${x.extracted_text_chars} תווים`:''}</span><div className="inline-actions"><b>{x.analysis_status==='ANALYZED'?'נותח ✓':'ממתין'}</b>{x.analysis_status==='ANALYZED'&&<button className="mini-button" onClick={async()=>{await setReportExampleStyleApproval(x.id,!x.is_approved_for_style,typeId);setExamples(await loadReportExamples(typeId));setSaved(x.is_approved_for_style?'הדוגמה הוסרה מלמידת הסגנון':'הדוגמה אושרה ללמידת הסגנון')}}>{x.is_approved_for_style?'הסר מהסגנון':'אשר לסגנון'}</button>}</div></div>)}</div></div></div></section></>
}
function ReportEditor({report,setReport,save,approve}:{report:DraftReport;setReport:(r:DraftReport)=>void;save:(s:ReportSection[])=>void;approve:()=>void}){
 const[sections,setSections]=useState<ReportSection[]>(report.sections),[sourceIds,setSourceIds]=useState<string[]|null>(null),[versions,setVersions]=useState<any[]>([]),[showVersions,setShowVersions]=useState(false),[compare,setCompare]=useState<any|null>(null),[working,setWorking]=useState(''),[reopening,setReopening]=useState(false);
 useEffect(()=>{setSections(report.sections)},[report.versionNumber]);
 function edit(si:number,pi:number,text:string){setSections(prev=>prev.map((s,i)=>i!==si?s:{...s,paragraphs:s.paragraphs.map((p,j)=>j!==pi?p:{...p,text})}))}
 async function aiRewrite(si:number,pi:number,instruction:string){const p=sections[si].paragraphs[pi];setWorking(p.id);try{const r=await rewriteReportParagraph({report:{...report,sections},paragraphId:p.id,instruction});edit(si,pi,r.text)}finally{setWorking('')}}
 async function history(){const v=await loadReportVersions(report.reportId);setVersions(v);setShowVersions(true)}
 const sources=sourceIds?report.sources.filter(s=>sourceIds.includes(s.id)):[];
 return <><section className="report-editor-head"><div><span className="eyebrow">{report.reportTypeName} · גרסה {report.versionNumber}</span><h1>טיוטת דוח</h1><p>מוכנות: {report.readinessScore}% · {report.sources.length} מקורות זמינים</p></div><div className="inline-actions"><button className="secondary-button" onClick={history}>היסטוריית גרסאות</button><button className="secondary-button" disabled={report.status!=='APPROVED'} title={report.status!=='APPROVED'?'יש לאשר את הדוח לפני ייצוא':''} onClick={()=>exportReportFile(report,sections,"DOCX")}>Word</button><button className="secondary-button" disabled={report.status!=='APPROVED'} onClick={()=>exportReportFile(report,sections,"PDF")}>PDF</button><button className="secondary-button" disabled={report.status==='APPROVED'} onClick={()=>save(sections)}>שמור גרסה</button>{report.status==='APPROVED'?<button className="secondary-button" onClick={()=>setReopening(true)}>פתח מחדש לעריכה</button>:<button className="primary-button compact" onClick={approve}>אשר דוח</button>}</div></section><section className="editor-layout"><article className="report-paper">{sections.map((s,si)=><section className="report-section" key={s.id}><h2>{s.title}</h2>{s.paragraphs.map((p,pi)=><div className="report-paragraph" key={p.id}><textarea disabled={report.status==='APPROVED'} value={p.text} onChange={e=>edit(si,pi,e.target.value)}/><div className="paragraph-tools"><button disabled={report.status==='APPROVED'||working===p.id} onClick={()=>aiRewrite(si,pi,'קצר את הפסקה בלי לאבד מידע מהותי')}>קצר</button><button disabled={report.status==='APPROVED'||working===p.id} onClick={()=>aiRewrite(si,pi,'נסח בצורה מקצועית ובהירה יותר')}>מקצועי יותר</button><button disabled={report.status==='APPROVED'||working===p.id} onClick={()=>aiRewrite(si,pi,'נסח בטון חיובי ומאוזן בלי להסתיר קשיים')}>חיובי יותר</button><button className="source-button" onClick={()=>setSourceIds(p.sourceIds)}>על סמך מה? · {p.sourceIds.length}</button></div></div>)}</section>)}</article><aside className="sources-panel"><span className="eyebrow">שקיפות AI</span><h2>מקורות</h2>{sourceIds===null?<p>לחצי על "על סמך מה?" ליד פסקה כדי לראות את המקורות שלה.</p>:sources.length?sources.map(s=><div className="source-card" key={s.id}><b>{s.label}</b><p>{s.excerpt}</p></div>):<div className="warning-line">⚠ לפסקה זו אין מקור מספק. יש לבדוק אותה לפני אישור.</div>}</aside></section>{showVersions&&<ModalShell title="היסטוריית גרסאות" close={()=>setShowVersions(false)}><div className="version-list">{versions.length?versions.map(v=><div className="version-row" key={v.id}><div><b>גרסה {v.version_number}</b><span>{v.generation_type} · {new Date(v.created_at).toLocaleString('he-IL')}</span></div><button className="secondary-button" onClick={async()=>{const restored=await restoreReportVersion(report,v);setReport(restored);setShowVersions(false)}}>שחזר כגרסה חדשה</button><button className="secondary-button" onClick={()=>setCompare(v)}>השווה לנוכחית</button></div>):<Empty text="אין עדיין גרסאות קודמות"/>}</div>{compare&&<div className="compare-box"><h3>השוואה: גרסה {compare.version_number} מול גרסה {report.versionNumber}</h3><div className="compare-cols"><div><b>גרסה {compare.version_number}</b>{(compare.content_json?.sections??[]).map((s:any)=><div className="compare-section" key={s.id}><h4>{s.title}</h4>{s.paragraphs?.map((p:any)=><p key={p.id}>{p.text}</p>)}</div>)}</div><div><b>גרסה {report.versionNumber}</b>{sections.map(s=><div className="compare-section" key={s.id}><h4>{s.title}</h4>{s.paragraphs.map(p=><p className={(compare.content_json?.sections??[]).flatMap((x:any)=>x.paragraphs??[]).find((x:any)=>x.id===p.id)?.text!==p.text?'changed':''} key={p.id}>{p.text}</p>)}</div>)}</div></div></div>}</ModalShell>}{reopening&&<ModalShell title="פתיחת דוח מאושר לעריכה" close={()=>setReopening(false)}><p>פתיחה מחדש תבטל את האישור הנוכחי. לאחר השינויים יהיה צורך לאשר את הדוח מחדש לפני ייצוא.</p><button className="primary-button" onClick={async()=>{await reopenReport(report.reportId,'נפתח מחדש לעריכה על ידי המשתמש');setReport({...report,status:'DRAFT'});setReopening(false)}}>פתח מחדש</button></ModalShell>}</>
}
function RecurringTaskForm({children,close,save}:{children:DbChild[];close:()=>void;save:(v:{childId?:string;title:string;priority:string;frequency:'WEEKLY'|'MONTHLY';intervalValue?:number})=>void}){
 const[title,setTitle]=useState(''),[childId,setChild]=useState(''),[priority,setPriority]=useState('NORMAL'),[frequency,setFrequency]=useState<'WEEKLY'|'MONTHLY'>('WEEKLY'),[intervalValue,setInterval]=useState(1);
 return <ModalShell title="משימה חוזרת" close={close}><label>שם המשימה</label><input value={title} onChange={e=>setTitle(e.target.value)}/><label>ילד</label><select value={childId} onChange={e=>setChild(e.target.value)}><option value="">כללי</option>{children.map(c=><option key={c.id} value={c.id}>{full(c)}</option>)}</select><label>תדירות</label><select value={frequency} onChange={e=>setFrequency(e.target.value as any)}><option value="WEEKLY">שבועית</option><option value="MONTHLY">חודשית</option></select><label>כל כמה תקופות</label><input type="number" min="1" value={intervalValue} onChange={e=>setInterval(Number(e.target.value))}/><label>עדיפות</label><select value={priority} onChange={e=>setPriority(e.target.value)}><option value="NORMAL">רגילה</option><option value="HIGH">גבוהה</option></select><button className="primary-button" disabled={!title.trim()} onClick={()=>save({childId:childId||undefined,title,priority,frequency,intervalValue})}>שמור משימה חוזרת</button></ModalShell>
}
function CriterionForm({goals,close,save}:{goals:DbGoal[];close:()=>void;save:(goalId:string,description:string)=>void}){
 const[goalId,setGoal]=useState(goals[0]?.id||''),[description,setDescription]=useState('');
 return <ModalShell title="מדד הצלחה חדש" close={close}><label>יעד</label><select value={goalId} onChange={e=>setGoal(e.target.value)}>{goals.map(g=><option key={g.id} value={g.id}>{g.title}</option>)}</select><label>מה ייחשב הצלחה?</label><textarea value={description} onChange={e=>setDescription(e.target.value)} placeholder="לדוגמה: יוזם פנייה לילד אחר ללא תיווך"/><button className="primary-button" disabled={!goalId||!description.trim()} onClick={()=>save(goalId,description)}>הוסף מדד</button></ModalShell>
}
function Empty({text}:{text:string}){return <div className="empty-state"><Plus/><b>{text}</b><span>אפשר להוסיף פריט חדש באמצעות כפתור ה־+</span></div>}
function ModalShell({title,close,children}:{title:string;close:()=>void;children:React.ReactNode}){return <div className="modal-backdrop"><div className="modal-card"><div className="quick-doc-head"><div><span className="eyebrow">קידום+</span><h2>{title}</h2></div><button className="close-button" onClick={close}>×</button></div>{children}</div></div>}
function ChildForm({current,close,save}:{current:DbChild|null;close:()=>void;save:(v:Partial<DbChild>)=>void}){const[f,setF]=useState({first_name:current?.first_name||'',last_name:current?.last_name||'',birth_date:current?.birth_date||'',framework_name:current?.framework_name||'',class_name:current?.class_name||''});return <ModalShell title={current?'עריכת ילד':'ילד חדש'} close={close}><div className="form-grid"><Field l="שם פרטי" v={f.first_name} s={v=>setF({...f,first_name:v})}/><Field l="שם משפחה" v={f.last_name} s={v=>setF({...f,last_name:v})}/><Field l="תאריך לידה" v={f.birth_date} s={v=>setF({...f,birth_date:v})} type="date"/><Field l="מסגרת" v={f.framework_name} s={v=>setF({...f,framework_name:v})}/><Field l="כיתה / קבוצה" v={f.class_name} s={v=>setF({...f,class_name:v})}/></div><button className="primary-button" disabled={!f.first_name||!f.last_name} onClick={()=>save(f)}>שמור</button></ModalShell>}
function GoalForm({close,save}:{close:()=>void;save:(v:{title:string;description?:string;baseline:number;target:number;targetDate?:string})=>void}){const[t,setT]=useState(''),[d,setD]=useState(''),[b,setB]=useState(20),[g,setG]=useState(80),[date,setDate]=useState('');return <ModalShell title="יעד חדש" close={close}><Field l="שם היעד" v={t} s={setT}/><label>תיאור</label><textarea value={d} onChange={e=>setD(e.target.value)}/><div className="form-grid"><Field l="רמת פתיחה %" v={String(b)} s={v=>setB(Number(v))} type="number"/><Field l="רמת יעד %" v={String(g)} s={v=>setG(Number(v))} type="number"/><Field l="תאריך יעד" v={date} s={setDate} type="date"/></div><button className="primary-button" disabled={!t} onClick={()=>save({title:t,description:d,baseline:b,target:g,targetDate:date||undefined})}>צור יעד</button></ModalShell>}
function ProgressForm({goals,close,save}:{goals:DbGoal[];close:()=>void;save:(g:DbGoal,v:number,n:string)=>void}){const[g,setG]=useState(goals[0]?.id||''),[v,setV]=useState(50),[n,setN]=useState('');const goal=goals.find(x=>x.id===g);return <ModalShell title="עדכון התקדמות" close={close}><label>יעד</label><select value={g} onChange={e=>setG(e.target.value)}>{goals.map(x=><option key={x.id} value={x.id}>{x.title}</option>)}</select><Field l="התקדמות %" v={String(v)} s={x=>setV(Number(x))} type="number"/><label>הערה</label><textarea value={n} onChange={e=>setN(e.target.value)}/><button className="primary-button" disabled={!goal} onClick={()=>goal&&save(goal,v,n)}>שמור עדכון</button></ModalShell>}
function TaskForm({children,close,save}:{children:DbChild[];close:()=>void;save:(v:{childId?:string;title:string;description?:string;priority:string;dueAt?:string})=>void}){const[t,setT]=useState(''),[c,setC]=useState(''),[p,setP]=useState('NORMAL'),[due,setDue]=useState('');return <ModalShell title="משימה חדשה" close={close}><Field l="שם המשימה" v={t} s={setT}/><label>ילד</label><select value={c} onChange={e=>setC(e.target.value)}><option value="">משימה כללית</option>{children.map(x=><option value={x.id} key={x.id}>{full(x)}</option>)}</select><label>עדיפות</label><select value={p} onChange={e=>setP(e.target.value)}><option>NORMAL</option><option>HIGH</option><option>LOW</option></select><Field l="מועד" v={due} s={setDue} type="datetime-local"/><button className="primary-button" disabled={!t} onClick={()=>save({childId:c||undefined,title:t,priority:p,dueAt:due||undefined})}>צור משימה</button></ModalShell>}
function DocForm({child,close,save}:{child:DbChild;close:()=>void;save:(v:{type:string;mood:string;summary:string})=>void}){const[t,setT]=useState('מפגש'),[m,setM]=useState('טוב'),[s,setS]=useState('');return <ModalShell title="תיעוד מהיר" close={close}><p>עבור <b>{full(child)}</b></p><label>סוג</label><select value={t} onChange={e=>setT(e.target.value)}><option>מפגש</option><option>תצפית</option><option>שיחה</option></select><label>איך היה?</label><select value={m} onChange={e=>setM(e.target.value)}><option>מצוין</option><option>טוב</option><option>בינוני</option><option>קשה</option></select><label>מה היה משמעותי?</label><textarea value={s} onChange={e=>setS(e.target.value)} placeholder="כמה מילים מספיקות..."/><button className="primary-button" disabled={!s.trim()} onClick={()=>save({type:t,mood:m,summary:s})}>שמור תיעוד</button></ModalShell>}
function Field({l,v,s,type='text'}:{l:string;v:string;s:(v:string)=>void;type?:string}){return <div><label>{l}</label><input type={type} value={v} onChange={e=>s(e.target.value)}/></div>}
